 6	public class BalancedParentheses {
 7	    private static final Map<Character, Character> MATCHING_OPENERS = Map.of(
 8	        ')', '(',
 9	        '}', '{',
10	        ']', '['
11	    );
12	    private static final Set<Character> OPENING_BRACKETS = Set.copyOf(MATCHING_OPENERS.values());
13	    private static final String DEFAULT_SAMPLE = "[()()]{}";
14	
15	    private BalancedParentheses() {}
16	
17	    public static boolean isBalanced(String s) {
18	        Deque<Character> brackets = new ArrayDeque<>();
19	
20	        for (int i = 0; i < s.length(); i++) {
21	            char c = s.charAt(i);
22	
23	            if (OPENING_BRACKETS.contains(c)) {
24	                brackets.push(c);
25	                continue;
26	            }
27	
28	            if (MATCHING_OPENERS.containsKey(c)) {
29	                if (brackets.isEmpty() || !hasExpectedOpeningBracket(brackets.pop(), c)) {
30	                    return false;
31	                }
32	            }
33	        }
34	
35	        return brackets.isEmpty();
36	    }
37	
38	    private static boolean hasExpectedOpeningBracket(char openingBracket, char closingBracket) {
39	        return MATCHING_OPENERS.get(closingBracket) == openingBracket;
40	    }
