 4	public class BalancedParentheses {
 5	    private static final String DEFAULT_SAMPLE = "[()()]{}";
 6	
 7	    private BalancedParentheses() {}
 8	
 9	    public static boolean isBalanced(String s) {
10	        Deque<BracketPair> openBrackets = new ArrayDeque<>();
11	
12	        for (int i = 0; i < s.length(); i++) {
13	            char c = s.charAt(i);
14	            BracketPair openingBracket = BracketPair.fromOpening(c);
15	
16	            if (openingBracket != null) {
17	                openBrackets.push(openingBracket);
18	                continue;
19	            }
20	
21	            BracketPair closingBracket = BracketPair.fromClosing(c);
22	            if (closingBracket != null) {
23	                if (openBrackets.isEmpty() || openBrackets.pop() != closingBracket) {
24	                    return false;
25	                }
26	            }
27	        }
28	
29	        return openBrackets.isEmpty();
30	    }
31	
32	    public static void main(String[] args) {
33	        String s = args.length > 0 ? args[0] : DEFAULT_SAMPLE;
34	        System.out.println((isBalanced(s) ? "true" : "false"));
35	    }
