37	    private enum BracketPair {
38	        PARENTHESES('(', ')'),
39	        BRACES('{', '}'),
40	        BRACKETS('[', ']');
41	
42	        private final char opening;
43	        private final char closing;
44	
45	        BracketPair(char opening, char closing) {
46	            this.opening = opening;
47	            this.closing = closing;
48	        }
49	
50	        private static BracketPair fromOpening(char candidate) {
51	            for (BracketPair pair : values()) {
52	                if (pair.opening == candidate) {
53	                    return pair;
54	                }
55	            }
56	
57	            return null;
58	        }
59	
60	        private static BracketPair fromClosing(char candidate) {
61	            for (BracketPair pair : values()) {
62	                if (pair.closing == candidate) {
63	                    return pair;
64	                }
65	            }
66	
67	            return null;
68	        }
69	    }
70	}

